const BROWSER_AUTOMATION_KEYWORDS = /\b(open|search|find|compare|book|reserve|buy|order|translate|navigate|route|directions|hotel|flight|train|bus|restaurant|website|webpage|page|shop|checkout|form|forms|fill|register|registration|signup|sign\s+up)\b/i;

function inferBrowserMissionMode(text: string): BrowserAgentMode {
  const source = text.toLowerCase();
  if (/\b(route|direction|directions|map|maps|navigate|navigation)\b/i.test(text)) {
    return "route";
  }
  if (/\b(hotel|stay|airbnb|booking\.com)\b/i.test(text)) {
    return "hotel";
  }
  if (/\b(book|booking|reserve|reservation|buy\s+ticket|purchase|register|registration|fill\s+form)\b/i.test(text)) {
    return "booking";
  }
  if (/\b(translate|translation)\b/i.test(text)) {
    return "translate";
  }
  if (/\b(explain|explanation|summarize this page|page explain)\b/i.test(text)) {
    return "explain";
  }
  if (/\b(contact|whatsapp|email|message|call)\b/i.test(text)) {
    return "contact";
  }
  if (/\b(research|deep research|compare|best options|alternatives|sources)\b/i.test(text)) {
    return "research";
  }
  if (source.includes("browser") || source.includes("webpage") || source.includes("website")) {
    return "browser";
  }
  return "browser";
}

function shouldRouteBrowserMission(text: string): boolean {
  const trimmed = text.trim();
  if (!trimmed) {
    return false;
  }
  if (/^https?:\/\//i.test(trimmed)) {
    return true;
  }
  if (/\bwww\.[^\s/]+\.[a-z]{2,}/i.test(trimmed)) {
    return true;
  }
  if (BROWSER_AUTOMATION_KEYWORDS.test(trimmed)) {
    return true;
  }
  const intent = detectComposerIntent(trimmed);
  return intent === "internet" || intent === "shopping" || intent === "movies" || intent === "songs";
}

const CLOUD_RESPONSE_STYLE_INSTRUCTIONS = `When answering with cloud data or live web research, format your response beautifully using Markdown and professional emojis. For biographies or concepts, give an exhaustive deep-dive. However, if the user asks for a RECIPE, tutorial, or instructions, you MUST directly provide the exact ingredients, measurements, and numbered steps. DO NOT write verbose filler. If the retrieved web data lacks the actual recipe steps, utilize your own internal knowledge to provide a perfect standard recipe.`;
const MAP_ROUTING_INSTRUCTIONS = `If the user asks for planning, directions, or maps, include navigation route guidance and shareable route URLs for Google Maps, Apple Maps, or any compatible maps app.`;
const PROACTIVE_ASSISTANT_STYLE_INSTRUCTIONS = `Always ask if the user wants you to continue, offer to take the next step for them, and prefer actions that make the user's work easier and faster without forcing a specific path.`;
const MAP_REQUEST_KEYWORDS = /\b(route|directions|navigate|maps?|location|address|way|drive|walk|transit)\b/i;

const detectSearchLanguage = (text: string) => {
  const trimmed = text.trim();
  if (!trimmed) {
    return "en";
  }
  if (/[-]/.test(trimmed) && !/[^-]/.test(trimmed)) {
    return "en";
  }
  if (/[-]/.test(trimmed) && /[\u0900-\u097F]/.test(trimmed)) {
    return "hi";
  }
  if (/[-]/.test(trimmed) && /[\u0A80-\u0AFF]/.test(trimmed)) {
    return "gu";
  }
  if (/[-]/.test(trimmed) && /[\u0400-\u04FF]/.test(trimmed)) {
    return "ru";
  }
  if (/[\u0600-\u06FF]/.test(trimmed)) {
    return "ar";
  }
  if (/[-\u007F]/.test(trimmed) && /[\u4E00-\u9FFF]/.test(trimmed)) {
    return "zh";
  }
  if (/[-\u007F]/.test(trimmed) && /[\u3040-\u30FF]/.test(trimmed)) {
    return "ja";
  }
  if (/[-\u007F]/.test(trimmed) && /[\u1100-\u11FF\u3130-\u318F\uAC00-\uD7AF]/.test(trimmed)) {
    return "ko";
  }
  return "en";
};

function normalizeBrowserAgentUrl(value: string): string {
  const trimmed = value.trim();
  if (!trimmed) {
    return BROWSER_AGENT_DEFAULT_URL;
  }
  if (/^(https?|mailto|tel|whatsapp):\/\//i.test(trimmed) || /^mailto:|^tel:|^whatsapp:/i.test(trimmed)) {
    return trimmed;
  }
  if (/^[\w.-]+\.[a-z]{2,}([/?#].*)?$/i.test(trimmed)) {
    return `https://${trimmed}`;
  }
  const lang = detectSearchLanguage(trimmed);
  const params = new URLSearchParams({ q: trimmed, hl: lang });
  if (lang === "gu") {
    params.set("lr", "lang_gu");
  }
  return `https://www.google.com/search?${params.toString()}`;
}

const BARE_GREETINGS_LIST = new Set([
  "hi", "hello", "hey", "hi there", "hello there", "good morning",
  "good afternoon", "good evening", "yo", "sup", "howdy", "thanks",
  "thank you", "ok", "okay", "yes", "no", "bye", "goodbye", "cool",
  "help", "who are you", "what can you do"
]);

function isBareGreetingText(val: string): boolean {
  const c = (val || "").toLowerCase().trim().replace(/[?!.,]/g, "");
  return c.length < 3 || BARE_GREETINGS_LIST.has(c);
}

function buildAugmentedRequestText(text: string, useCloud: boolean, isMapRequest: boolean): string {
  if (isBareGreetingText(text)) {
    return text;
  }
  const instructions: string[] = [];
  const lang = detectSearchLanguage(text);
  if (lang !== "en") {
    instructions.unshift(
      `This input appears to be in ${lang}. Translate it to English for internal reasoning, then answer in the original language unless the user asks otherwise.`,
    );
  }
  if (useCloud) {
    instructions.push(CLOUD_RESPONSE_STYLE_INSTRUCTIONS);
  }
  if (isMapRequest) {
    instructions.push(MAP_ROUTING_INSTRUCTIONS);
  }
  instructions.push(
    "Respond with enough detail to be genuinely useful. Prefer a rich, structured answer with examples, caveats, next steps, and clear reasoning when applicable. Do not be terse unless the user explicitly asks for brevity.",
  );
  return `${text}\n\n${instructions.join("\n")}`;
}

function encodeBrowserAgentQuery(value: string): string {
  return encodeURIComponent(value.trim().replace(/\s+/g, " "));
}

function digitsForWhatsApp(value: string): string {
  return value.replace(/[^\d]/g, "");
}

