const termsKeyForUser = (uid?: string | null) => (uid ? `${STORAGE_TERMS_ACCEPTED}:${uid}` : STORAGE_TERMS_PENDING);

const readTermsAccepted = (uid?: string | null) => {
  if (typeof localStorage === "undefined") {
    return false;
  }
  try {
    return Boolean(localStorage.getItem(termsKeyForUser(uid)));
  } catch {
    return false;
  }
};

const persistTermsAccepted = (uid?: string | null) => {
  if (typeof localStorage === "undefined") {
    return;
  }
  try {
    localStorage.setItem(termsKeyForUser(uid), String(Date.now()));
  } catch {
    // ignore storage failures
  }
};

const clearTermsAccepted = (uid?: string | null) => {
  if (typeof localStorage === "undefined") {
    return;
  }
  try {
    if (uid) {
      localStorage.removeItem(termsKeyForUser(uid));
    }
    localStorage.removeItem(STORAGE_TERMS_PENDING);
  } catch {
    // ignore storage failures
  }
};

function storageKeyForUser(base: string, uid?: string | null): string {
  return uid ? `${base}:${uid}` : base;
}

type UserContextPrefs = {
  enabled: boolean;
  includeDisplayName: boolean;
  includeEmail: boolean;
  includePhone: boolean;
  includeUid: boolean;
  includeEmailVerified: boolean;
  includeProfileNotes: boolean;
  includeCustomFacts: boolean;
  includeChatMemory: boolean;
  chatMemoryMaxSessions: number;
  chatMemoryMaxSnippetsPerSession: number;
};

type AgentMemoryEntry = {
  id: string;
  text: string;
  source: "automatic" | "interaction";
  createdAt: number;
  updatedAt: number;
};

function normalizeAgentMemory(input: unknown): AgentMemoryEntry[] {
  if (!Array.isArray(input)) {
    return [];
  }
  const now = Date.now();
  const seen = new Set<string>();
  return input
    .map((item, index): AgentMemoryEntry | null => {
      if (!item || typeof item !== "object") {
        return null;
      }
      const record = item as Partial<AgentMemoryEntry>;
      const text = typeof record.text === "string" ? record.text.replace(/\s+/g, " ").trim().slice(0, 420) : "";
      const normalized = text.toLowerCase();
      if (!text || seen.has(normalized)) {
        return null;
      }
      seen.add(normalized);
      return {
        id: typeof record.id === "string" && record.id ? record.id : `memory-${index}-${now}`,
        text,
        source: record.source === "interaction" ? "interaction" : "automatic",
        createdAt: typeof record.createdAt === "number" ? record.createdAt : now,
        updatedAt: typeof record.updatedAt === "number" ? record.updatedAt : now,
      };
    })
    .filter((entry): entry is AgentMemoryEntry => Boolean(entry))
    .sort((a, b) => b.updatedAt - a.updatedAt)
    .slice(0, 60);
}

function loadAgentMemory(uid?: string | null): AgentMemoryEntry[] {
  return normalizeAgentMemory(parseJsonSafe<unknown>(localStorage.getItem(storageKeyForUser(STORAGE_AGENT_MEMORY, uid))));
}

function isSensitiveMemoryText(text: string): boolean {
  return /\b(?:password|passcode|otp|one[- ]time|api[_ -]?key|access[_ -]?token|secret|credit\s*card|cvv|bank\s*(?:account|number)|aadhaar|social\s*security)\b/i.test(text);
}

/**
 * Keep only durable, user-owned facts automatically. Full conversations are
 * already saved separately; this compact layer prevents important preferences
 * from getting buried while deliberately excluding credentials and secrets.
 */
function extractAutomaticMemory(text: string): string | null {
  const cleaned = text.replace(/\s+/g, " ").trim().slice(0, 420);
  if (cleaned.length < 8 || isSensitiveMemoryText(cleaned)) {
    return null;
  }
  const durableSignal = /(?:\bremember\b|\bkeep in mind\b|\bmy preference\b|\bi prefer\b|\bi like\b|\bi work\b|\bi live\b|\bmy timezone\b|\bcall me\b|\bmy name is\b|\balways\b|\bnever\b)/i;
  return durableSignal.test(cleaned) ? cleaned : null;
}

const DEFAULT_USER_CONTEXT_PREFS: UserContextPrefs = {
  enabled: true,
  includeDisplayName: true,
  includeEmail: true,
  includePhone: true,
  includeUid: false,
  includeEmailVerified: true,
  includeProfileNotes: true,
  includeCustomFacts: true,
  includeChatMemory: true,
  chatMemoryMaxSessions: 8,
  chatMemoryMaxSnippetsPerSession: 2,
};

function clampInteger(value: unknown, min: number, max: number, fallback: number): number {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) {
    return fallback;
  }
  return Math.max(min, Math.min(max, Math.round(parsed)));
}

function normalizeUserContextPrefs(input: unknown): UserContextPrefs {
  if (!input || typeof input !== "object") {
    return { ...DEFAULT_USER_CONTEXT_PREFS };
  }
  const record = input as Partial<UserContextPrefs>;
  return {
    enabled: typeof record.enabled === "boolean" ? record.enabled : DEFAULT_USER_CONTEXT_PREFS.enabled,
    includeDisplayName:
      typeof record.includeDisplayName === "boolean" ? record.includeDisplayName : DEFAULT_USER_CONTEXT_PREFS.includeDisplayName,
    includeEmail: typeof record.includeEmail === "boolean" ? record.includeEmail : DEFAULT_USER_CONTEXT_PREFS.includeEmail,
    includePhone: typeof record.includePhone === "boolean" ? record.includePhone : DEFAULT_USER_CONTEXT_PREFS.includePhone,
    includeUid: typeof record.includeUid === "boolean" ? record.includeUid : DEFAULT_USER_CONTEXT_PREFS.includeUid,
    includeEmailVerified:
      typeof record.includeEmailVerified === "boolean"
        ? record.includeEmailVerified
        : DEFAULT_USER_CONTEXT_PREFS.includeEmailVerified,
    includeProfileNotes:
      typeof record.includeProfileNotes === "boolean" ? record.includeProfileNotes : DEFAULT_USER_CONTEXT_PREFS.includeProfileNotes,
    includeCustomFacts:
      typeof record.includeCustomFacts === "boolean" ? record.includeCustomFacts : DEFAULT_USER_CONTEXT_PREFS.includeCustomFacts,
    includeChatMemory:
      typeof record.includeChatMemory === "boolean" ? record.includeChatMemory : DEFAULT_USER_CONTEXT_PREFS.includeChatMemory,
    chatMemoryMaxSessions: clampInteger(
      record.chatMemoryMaxSessions,
      1,
      24,
      DEFAULT_USER_CONTEXT_PREFS.chatMemoryMaxSessions,
    ),
    chatMemoryMaxSnippetsPerSession: clampInteger(
      record.chatMemoryMaxSnippetsPerSession,
      1,
      4,
      DEFAULT_USER_CONTEXT_PREFS.chatMemoryMaxSnippetsPerSession,
    ),
  };
}

function loadUserContextPrefs(uid?: string | null): UserContextPrefs {
  const parsed = parseJsonSafe<unknown>(localStorage.getItem(storageKeyForUser(STORAGE_USER_CONTEXT_PREFS, uid)));
  return normalizeUserContextPrefs(parsed);
}

