const isDesktopRuntime =
  typeof window !== "undefined" &&
  Boolean((window as { meera?: { windowControls?: { minimize: () => void; maximize: () => void; close: () => void } } }).meera
    ?.windowControls);
let firebaseApp: FirebaseApp | null = null;
let firebaseAuth: ReturnType<typeof getAuth> | null = null;

const applyAuthPersistence = async (auth: ReturnType<typeof getAuth>) => {
  try {
    // Keep desktop sign-in state across restarts instead of wiping it on every launch.
    await setPersistence(auth, browserLocalPersistence);
  } catch {
    // ignore persistence errors
  }
};

const initFirebaseAuth = (config: FirebaseConfig): ReturnType<typeof getAuth> => {
  const apps = getApps();
  if (apps.length > 0) {
    const existingApp = getApp();
    const existingConfig = existingApp.options as FirebaseConfig;
    if (!isSameFirebaseConfig(existingConfig, config)) {
      // Avoid duplicate app errors in hot reload / re-render situations.
      firebaseApp = existingApp;
    } else {
      firebaseApp = existingApp;
    }
  }
  if (!firebaseApp) {
    firebaseApp = initializeApp(config as FirebaseOptions);
  }
  if (!firebaseAuth || firebaseAuth.app !== firebaseApp) {
    firebaseAuth = getAuth(firebaseApp);
    void applyAuthPersistence(firebaseAuth);
  }
  return firebaseAuth as ReturnType<typeof getAuth>;
};

