type ModelOptionId = string;

const getBundledModelIds = (id: string | null | undefined): string[] => {
  return id ? [id] : [];
};

const resolveModelLabel = (id: string): string => {
  const normalized = normalizeLegacyModelOptionId(id);
  return MODEL_OPTIONS.find((option) => option.id === normalized)?.label ?? (normalized || id);
};

const isChatModelOption = (id: string | null | undefined): id is ModelOptionId => {
  const normalized = normalizeLegacyModelOptionId(id);
  if (!normalized) return false;
  // If it's in the hardcoded list, ensure it's chat capable
  if (MODEL_OPTIONS.some((option) => option.id === normalized)) {
    return MODEL_OPTIONS.some((option) => option.id === normalized && option.chatCapable !== false);
  }
  // Otherwise (e.g. cloud models), allow it
  return true;
};

const FRONTEND_TO_BACKEND_MODEL_ID_MAP: Record<string, string> = {
  "meera-ultra-7b": "meera-ultra-8b",
};

const toBackendModelId = (id: string): string => {
  const normalized = normalizeLegacyModelOptionId(id);
  return FRONTEND_TO_BACKEND_MODEL_ID_MAP[normalized] ?? normalized;
};

const normalizeCloudModelMap = (modelMap: Record<string, string> | null | undefined): Record<string, string> => {
  if (!modelMap || typeof modelMap !== "object") {
    return {};
  }
  return Object.entries(modelMap).reduce((acc, [key, value]) => {
    const normalizedKey = normalizeLegacyModelOptionId(key);
    const normalizedValue = typeof value === "string" ? value.trim() : "";
    if (isChatModelOption(normalizedKey) && normalizedValue) {
      acc[normalizedKey] = normalizedValue;
    }
    return acc;
  }, {} as Record<string, string>);
};

const resolveTierShortLabel = (id: string): string => resolveModelLabel(id).replace(/^Meera\s+/i, "").trim();

const formatLabelList = (labels: string[]): string => {
  if (labels.length <= 1) {
    return labels[0] ?? "";
  }
  if (labels.length === 2) {
    return `${labels[0]} and ${labels[1]}`;
  }
  return `${labels.slice(0, -1).join(", ")}, and ${labels[labels.length - 1]}`;
};

