function getComposerIntentSpec(intentId: ComposerIntentId): ComposerIntentSpec | undefined {
  if (intentId === "auto") {
    return undefined;
  }
  return COMPOSER_INTENT_SPECS.find((item) => item.id === intentId);
}

function isCloudRoutedIntent(intentId: ComposerIntentId): boolean {
  return getComposerIntentSpec(intentId)?.routeMode === "cloud";
}

