const NORMALIZED_COMMON_ENGLISH = Array.from(
  new Set(
    (commonEnglishWords as string[])
      .map((word) => String(word || "").trim().toLowerCase())
      .filter((word) => /^[a-z][a-z'-]{1,}$/.test(word))
      .slice(0, 10000),
  ),
);

const NORMALIZED_FULL_ENGLISH_DICTIONARY = Array.from(
  new Set(
    (englishDictionaryWords as string[])
      .map((word) => String(word || "").trim().toLowerCase())
      .filter((word) => /^[a-z][a-z'-]{1,}$/.test(word)),
  ),
);

const ENGLISH_DICTIONARY_BY_PREFIX = (() => {
  const map = new Map<string, string[]>();
  for (const word of NORMALIZED_FULL_ENGLISH_DICTIONARY) {
    const key = word.slice(0, 2);
    if (key.length < 2) {
      continue;
    }
    const list = map.get(key);
    if (list) {
      list.push(word);
    } else {
      map.set(key, [word]);
    }
  }
  for (const [key, words] of map.entries()) {
    const unique = Array.from(new Set(words));
    unique.sort();
    map.set(key, unique);
  }
  return map;
})();

