function getShareTargetVisual(target: ShareTarget): { Icon: IconType; accent: string; bg: string } {
  if (target.kind === "email") {
    return {
      Icon: MdEmail,
      accent: "#1d4ed8",
      bg: "linear-gradient(135deg, rgba(37, 99, 235, 0.45), rgba(59, 130, 246, 0.75))",
    };
  }

  if (target.kind === "whatsapp") {
    return {
      Icon: SiWhatsapp,
      accent: "#0f766e",
      bg: "linear-gradient(135deg, rgba(6, 95, 70, 0.45), rgba(15, 118, 110, 0.75))",
    };
  }

  if (target.kind === "copy") {
    return {
      Icon: MdContentCopy,
      accent: "#4338ca",
      bg: "linear-gradient(135deg, rgba(39, 39, 112, 0.45), rgba(76, 29, 149, 0.78))",
    };
  }

  const desktopVisual = getDesktopAppVisual(target.label, target.processName || "");
  return {
    ...desktopVisual,
    bg: `linear-gradient(135deg, rgba(10, 18, 36, 0.55), ${desktopVisual.accent}33)`,
  };
}

type SessionRowProps = {
  session: Session;
  active?: boolean;
  editing?: boolean;
  draftName?: string;
  preview: string;
  meta: string;
  variant: "card" | "sidebar";
  onOpen: () => void;
  onStartEdit: () => void;
  onDraftChange: (value: string) => void;
  onCommitEdit: () => void;
  onCancelEdit: () => void;
  onDelete: () => void;
  onRipple?: (event: React.PointerEvent<HTMLElement>) => void;
};

function SessionRow({
  session,
  active = false,
  editing = false,
  draftName = "",
  preview,
  meta,
  variant,
  onOpen,
  onStartEdit,
  onDraftChange,
  onCommitEdit,
  onCancelEdit,
  onDelete,
  onRipple,
}: SessionRowProps) {
  const showIcon = variant === "card";
  const displayTitle = variant === "sidebar" ? deriveSessionHeading(session) : session.name || DEFAULT_SESSION_NAME;
  return (
    <div className={`session-row session-row-${variant} ${active ? "session-row-active" : ""}`}>
      {editing ? (
        <div className="session-row-edit">
          <input
            className="session-row-input"
            value={draftName}
            autoFocus
            onChange={(event) => onDraftChange(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter") {
                event.preventDefault();
                onCommitEdit();
              }
              if (event.key === "Escape") {
                event.preventDefault();
                onCancelEdit();
              }
            }}
          />
          <button
            className="session-row-action meera-ripple"
            type="button"
            aria-label="Save title"
            onClick={onCommitEdit}
            onPointerDown={onRipple}
          >
            <PiCheck />
          </button>
          <button
            className="session-row-action meera-ripple"
            type="button"
            aria-label="Cancel rename"
            onClick={onCancelEdit}
            onPointerDown={onRipple}
          >
            <PiX />
          </button>
        </div>
      ) : (
        <>
          <button type="button" className="session-row-main meera-ripple" onClick={onOpen} onPointerDown={onRipple}>
            {showIcon && (
              <span className="session-row-icon material-symbols-outlined" aria-hidden="true">
                {SIDEBAR_ICON_NAMES.session}
              </span>
            )}
            <span className="session-row-copy">
              <span className="session-row-title">{displayTitle}</span>
              {preview ? <span className="session-row-preview">{preview}</span> : null}
              <span className="session-row-meta">{meta}</span>
            </span>
          </button>
          <div className="session-row-actions">
            <button
              className="session-row-action meera-ripple"
              type="button"
              aria-label="Rename chat"
              onClick={(event) => {
                event.stopPropagation();
                onStartEdit();
              }}
              onPointerDown={onRipple}
            >
              <span className="session-row-action-icon material-symbols-outlined" aria-hidden="true">
                {SIDEBAR_ICON_NAMES.edit}
              </span>
            </button>
            <button
              className="session-row-action meera-ripple"
              type="button"
              aria-label="Delete chat"
              onClick={(event) => {
                event.stopPropagation();
                onDelete();
              }}
              onPointerDown={onRipple}
            >
              <span className="session-row-action-icon material-symbols-outlined" aria-hidden="true">
                {SIDEBAR_ICON_NAMES.delete}
              </span>
            </button>
          </div>
        </>
      )}
    </div>
  );
}

function readFileAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(typeof reader.result === "string" ? reader.result : "");
    reader.onerror = () => reject(reader.error ?? new Error("Unable to read file"));
    reader.readAsDataURL(file);
  });
}

async function readFileAsBase64(file: File): Promise<string> {
  const dataUrl = await readFileAsDataUrl(file);
  return dataUrl.includes(",") ? dataUrl.split(",", 2)[1] ?? "" : dataUrl;
}

function formatAttachmentSize(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes <= 0) {
    return "0 KB";
  }
  if (bytes >= 1024 * 1024) {
    return `${(bytes / (1024 * 1024)).toFixed(bytes >= 10 * 1024 * 1024 ? 0 : 1)} MB`;
  }
  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
}

function stripThinkingBlocks(content: string): string {
  let processed = content ?? "";
  processed = processed.replace(/<think>([\s\S]*?)<\/think>/gi, "");
  processed = processed.replace(/<thinking>([\s\S]*?)<\/thinking>/gi, "");
  processed = processed.replace(/<tool_result>([\s\S]*?)<\/tool_result>/gi, "");
  processed = processed.replace(/<tool_call\b[^>]*>[\s\S]*?<\/tool_call>/gi, "");
  processed = processed.replace(/<tool_call\b[^>]*>[\s\S]*$/gi, "");
  processed = processed.replace(/<\|tool_call>[\s\S]*?<tool_call\|>/gi, "");
  processed = processed.replace(/<\|tool_call>[\s\S]*$/gi, "");
  processed = processed.replace(/<thought>([\s\S]*?)<\/thought>/gi, "");
  processed = processed.replace(/<reasoning>([\s\S]*?)<\/reasoning>/gi, "");
  processed = processed.replace(/<reason>([\s\S]*?)<\/reason>/gi, "");
  processed = processed.replace(/```think[\s\S]*?```/gi, "");
  processed = processed.replace(/<think>([\s\S]*)$/gi, "");
  processed = processed.replace(/<thinking>([\s\S]*)$/gi, "");
  processed = processed.replace(/<tool_result>([\s\S]*)$/gi, "");
  processed = processed.replace(/<tool_call\b[^>]*>[\s\S]*$/gi, "");
  processed = processed.replace(/<\|tool_call>[\s\S]*$/gi, "");
  processed = processed.replace(/<thought>([\s\S]*)$/gi, "");
  processed = processed.replace(/<reasoning>([\s\S]*)$/gi, "");
  processed = processed.replace(/<reason>([\s\S]*)$/gi, "");
  // Defense in depth: some models emit an inline plain-text "thinking:" preamble
  // (no tags) as the very first thing in content, which older backends may pass
  // through untouched. Strip a leading such preamble only — never mid-answer text.
  processed = processed.replace(/^\s*thinking\s*:?\s*\n[\s\S]*?\n\s*\n/i, "");
  return processed;
}

const LANG_ALIAS_PRIORITY: Array<{ lang: string; score: number; patterns: RegExp[] }> = [
  { lang: "python", score: 3, patterns: [/^\s*def\s+\w+\(/m, /^\s*import\s+\w+/m, /^\s*from\s+\w+\s+import\s+/m, /\bprint\(/m, /:\s*$/m] },
  { lang: "javascript", score: 3, patterns: [/\bconst\s+\w+\s*=/m, /\blet\s+\w+\s*=/m, /\bfunction\s+\w+\(/m, /=>/m, /\bconsole\.log\(/m] },
  { lang: "typescript", score: 4, patterns: [/\binterface\s+\w+/m, /\btype\s+\w+\s*=/m, /:\s*(string|number|boolean|unknown|any)\b/m, /\bimplements\b/m] },
  { lang: "java", score: 3, patterns: [/\bpublic\s+class\s+\w+/m, /\bpublic\s+static\s+void\s+main/m, /\bSystem\.out\.println\(/m] },
  { lang: "cpp", score: 3, patterns: [/#include\s*<\w+>/m, /\bstd::\w+/m, /\bint\s+main\s*\(/m] },
  { lang: "csharp", score: 3, patterns: [/\bnamespace\s+\w+/m, /\busing\s+System\b/m, /\bpublic\s+class\s+\w+/m, /\bConsole\.WriteLine\(/m] },
  { lang: "go", score: 3, patterns: [/\bpackage\s+main\b/m, /\bfunc\s+main\s*\(/m, /\bfmt\.Println\(/m] },
  { lang: "rust", score: 3, patterns: [/\bfn\s+main\s*\(/m, /\blet\s+mut\s+\w+/m, /\bprintln!\(/m] },
  { lang: "sql", score: 3, patterns: [/\bselect\s+.+\bfrom\b/im, /\binsert\s+into\b/im, /\bupdate\s+\w+\s+set\b/im, /\bjoin\b/im] },
  { lang: "html", score: 3, patterns: [/<html[\s>]/im, /<div[\s>]/im, /<\/\w+>/m] },
  { lang: "css", score: 3, patterns: [/\.[\w-]+\s*\{/m, /#[\w-]+\s*\{/m, /\b(color|font-size|margin|padding)\s*:/m] },
  { lang: "bash", score: 3, patterns: [/^\s*#!/m, /\b(curl|grep|awk|sed|chmod|export)\b/m, /^\s*(sudo\s+)?apt\b/m] },
  { lang: "json", score: 3, patterns: [/^\s*\{\s*\"/m, /\"\w+\"\s*:\s*(\"|\{|\[|\d|true|false|null)/m] },
  { lang: "markdown", score: 2, patterns: [/^\s*#{1,6}\s+/m, /^\s*[-*+]\s+/m, /\[[^\]]+\]\([^)]+\)/m] },
];

function detectCodeLanguage(text: string): string {
  const value = (text || "").trim();
  if (!value) {
    return "text";
  }
  let best = { lang: "text", score: 0 };
  for (const entry of LANG_ALIAS_PRIORITY) {
    let score = 0;
    for (const pattern of entry.patterns) {
      if (pattern.test(value)) {
        score += entry.score;
      }
    }
    if (score > best.score) {
      best = { lang: entry.lang, score };
    }
  }
  return best.lang;
}

function parseFencedCodeBlocks(text: string): DetectedCodeSegment[] {
  const blocks: DetectedCodeSegment[] = [];
  const regex = /```([a-zA-Z0-9_+-]*)\n([\s\S]*?)```/g;
  let match: RegExpExecArray | null = null;
  while ((match = regex.exec(text)) !== null) {
    const langRaw = (match[1] || "").trim().toLowerCase();
    const content = (match[2] || "").trim();
    if (!content) {
      continue;
    }
    blocks.push({
      language: langRaw || detectCodeLanguage(content),
      content,
    });
  }
  return blocks;
}

function detectCodeSegments(text: string): DetectedCodeSegment[] {
  const fenced = parseFencedCodeBlocks(text);
  if (fenced.length > 0) {
    return fenced;
  }
  const chunks = text
    .split(/\n{2,}/)
    .map((part) => part.trim())
    .filter(Boolean);
  if (chunks.length <= 1) {
    return [{ language: detectCodeLanguage(text), content: text.trim() }];
  }
  const segments: DetectedCodeSegment[] = [];
  for (const chunk of chunks) {
    const lang = detectCodeLanguage(chunk);
    segments.push({ language: lang, content: chunk });
  }
  return segments;
}

function looksLikeTable(text: string): boolean {
  const lines = text
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);
  if (lines.length < 2) {
    return false;
  }
  const tabRows = lines.filter((line) => line.includes("\t"));
  if (tabRows.length >= 2) {
    return true;
  }
  const pipeRows = lines.filter((line) => /\|/.test(line));
  if (pipeRows.length >= 2) {
    return true;
  }
  const csvRows = lines.filter((line) => /,/.test(line));
  if (csvRows.length >= 2) {
    const width = csvRows[0].split(",").length;
    return width >= 2 && csvRows.slice(1).some((line) => line.split(",").length === width);
  }
  return false;
}

function normalizeTableCells(raw: string): string[] {
  const line = raw.trim().replace(/^\|/, "").replace(/\|$/, "");
  if (line.includes("\t")) {
    return line.split("\t").map((cell) => cell.trim());
  }
  if (line.includes("|")) {
    return line.split("|").map((cell) => cell.trim());
  }
  return line.split(",").map((cell) => cell.trim());
}

function convertToMarkdownTable(text: string): string {
  const rows = text
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);
  if (rows.length < 2) {
    return text;
  }
  const cells = rows.map(normalizeTableCells);
  const width = Math.max(...cells.map((row) => row.length));
  if (width < 2) {
    return text;
  }
  const normalizedRows = cells.map((row) => [...row, ...Array.from({ length: width - row.length }, () => "")]);
  const header = normalizedRows[0];
  const divider = Array.from({ length: width }, () => "---");
  const body = normalizedRows.slice(1);
  const lines = [
    `| ${header.join(" | ")} |`,
    `| ${divider.join(" | ")} |`,
    ...body.map((row) => `| ${row.join(" | ")} |`),
  ];
  return lines.join("\n");
}

function isMathIntent(text: string, manualMode: MathModeSetting = "auto"): SmartPromptAnalysis {
  const source = text || "";
  const normalized = source.toLowerCase();
  const mathContext = detectMathContext(source, manualMode);
  const isMath = mathContext.isMath;
  const hasIntegralIntent = mathContext.detectedTopics.includes("calculus") || /\b(integral|integrate|integration)\b/.test(normalized) || /\u222b/.test(source);
  const hasDerivativeIntent = mathContext.detectedTopics.includes("calculus") || /\b(derivative|differentiat|d\/dx)\b/.test(normalized) || /\u2202/.test(source);
  const hasMatrixIntent = mathContext.detectedTopics.includes("linear-algebra") || /\b(matrix|determinant|eigen|vector)\b/.test(normalized);
  const hasLimitIntent = /\blim[\s_{(]/i.test(source);
  const hasBulletOrNumbering = /(^|\n)\s*(?:[-*+]\s+|\d+[.)]\s+)/.test(source);
  const segments = detectCodeSegments(source);
  const languageSet = Array.from(
    new Set(
      segments
        .map((segment) => segment.language)
        .filter((lang) => lang && lang !== "text"),
    ),
  );
  const hasMixedLanguages = languageSet.length >= 2;
  const hasLikelyTable = looksLikeTable(source);
  return {
    isMath,
    hasIntegralIntent,
    hasDerivativeIntent,
    hasMatrixIntent,
    hasLimitIntent,
    hasBulletOrNumbering,
    detectedLanguages: languageSet,
    hasMixedLanguages,
    hasLikelyTable,
  };
}

function buildMultiLanguagePromptBundle(text: string): string {
  const segments = detectCodeSegments(text).filter((segment) => segment.content.trim());
  if (segments.length <= 1) {
    return text;
  }
  const unique = Array.from(new Set(segments.map((segment) => segment.language).filter((lang) => lang && lang !== "text")));
  if (unique.length < 2) {
    return text;
  }
  const files = segments.map((segment, index) => {
    const lang = segment.language || "text";
    const extMap: Record<string, string> = {
      python: "py",
      javascript: "js",
      typescript: "ts",
      java: "java",
      cpp: "cpp",
      csharp: "cs",
      go: "go",
      rust: "rs",
      sql: "sql",
      html: "html",
      css: "css",
      bash: "sh",
      json: "json",
      markdown: "md",
      text: "txt",
    };
    const ext = extMap[lang] ?? "txt";
    const fileName = `snippet_${index + 1}.${ext}`;
    return `File: ${fileName}\n\`\`\`${lang}\n${segment.content.trim()}\n\`\`\``;
  });
  return [
    "Detected multi-language input. Treat each file block independently, then provide integrated reasoning.",
    ...files,
  ].join("\n\n");
}

function isLikelyCodePaste(text: string): boolean {
  const value = (text || "").trim();
  if (!value) {
    return false;
  }
  const lines = value.split("\n").filter((line) => line.trim().length > 0);
  if (lines.length < 2) {
    return false;
  }
  const codeSignals = [
    /[{}()[\];]/,
    /\b(function|class|def|import|from|return|const|let|var|public|private|package)\b/,
    /=>/,
    /^\s*#/m,
    /^\s*<\w+/m,
  ];
  return codeSignals.some((pattern) => pattern.test(value));
}

function wrapCodeAsFileBlock(text: string, language: string): string {
  const lang = (language || "text").trim().toLowerCase();
  return `\`\`\`${lang}\n${text.trim()}\n\`\`\``;
}

function buildMathSolveEnvelope(text: string): string {
  const prompt = text.trim();
  if (!prompt) {
    return prompt;
  }
  return [
    "[MATH_MODE]",
    "Solve with exact symbols and structured steps.",
    "Rules:",
    "1. Preserve mathematical notation exactly.",
    "2. Show step-by-step derivation with compact numbered steps.",
    "3. If integration/differentiation/limits/matrices appear, keep symbolic form before numeric approximation.",
    "4. End with a single clearly labeled final answer line.",
    "",
    "Problem:",
    prompt,
  ].join("\n");
}

function prepareSmartPrompt(rawText: string, manualMode: MathModeSetting = "auto"): string {
  let next = rawText ?? "";
  const analysis = isMathIntent(next, manualMode);
  if (analysis.hasLikelyTable) {
    next = convertToMarkdownTable(next);
  }
  if (analysis.hasMixedLanguages) {
    next = buildMultiLanguagePromptBundle(next);
  }
  if (!analysis.hasMixedLanguages && analysis.detectedLanguages.length === 1 && parseFencedCodeBlocks(next).length === 0) {
    const detectedLanguage = analysis.detectedLanguages[0];
    if (detectedLanguage !== "text" && isLikelyCodePaste(next)) {
      next = wrapCodeAsFileBlock(next, detectedLanguage);
    }
  }
  
  if (analysis.isMath && !/\[MATH_MODE\]/.test(next)) {
    next = buildMathSolveEnvelope(next);
  } else if (!analysis.isMath && /\b(who is|who was|tell me about|explain|history of|biography of|what is|what was|what are)\b/i.test(next) && !/FORMATTING MANDATE/.test(next)) {
    // Inject a structural skeleton to force SLMs to write long, deep answers
    next = [
      next,
      "",
      "📝 FORMATTING MANDATE: Provide an EXHAUSTIVE, multi-section deep dive. You MUST use the following exact markdown structure and fill each section with maximum detail:",
      "## 🌟 Introduction & Overview",
      "## 📅 Background & History",
      "## 🚀 Key Milestones & Details",
      "## 📊 Major Achievements & Data",
      "## 💡 Conclusion",
      "Do NOT skip any section. Write at least one long, detailed paragraph per section using the retrieved data."
    ].join("\n");
  }
  
  return next.trim();
}

function hasUnresolvedPromptPlaceholders(text: string): boolean {
  const value = (text || "").trim();
  if (!value) {
    return false;
  }
  // Guard common template placeholders that should be filled by the user first.
  return /\[(topic|product|budget|problem|describe feature|feature|location|city|country)\]/i.test(value);
}

function stripMathSolveEnvelope(text: string): string {
  const value = (text || "").trim();
  if (!value.startsWith("[MATH_MODE]")) {
    return value;
  }
  const marker = "\nProblem:\n";
  const markerIndex = value.indexOf(marker);
  if (markerIndex === -1) {
    return value.replace(/^\[MATH_MODE\]\s*/i, "").trim();
  }
  return value.slice(markerIndex + marker.length).trim();
}

function getListContinuationPrefix(line: string): string {
  const checkboxMatch = /^(\s*)-\s\[( |x|X)\]\s+(.*)$/.exec(line);
  if (checkboxMatch) {
    const [, indent] = checkboxMatch;
    const content = (checkboxMatch[3] || "").trim();
    return content ? `${indent}- [ ] ` : "";
  }
  const bulletMatch = /^(\s*)([-*+])\s+(.*)$/.exec(line);
  if (bulletMatch) {
    const [, indent, bullet, content] = bulletMatch;
    return (content || "").trim() ? `${indent}${bullet} ` : "";
  }
  const numberMatch = /^(\s*)(\d+)([.)])\s+(.*)$/.exec(line);
  if (numberMatch) {
    const [, indent, numRaw, sep, content] = numberMatch;
    const current = Number.parseInt(numRaw, 10);
    if (!Number.isFinite(current) || current < 0) {
      return "";
    }
    return (content || "").trim() ? `${indent}${current + 1}${sep} ` : "";
  }
  return "";
}

function continueListAtCursor(value: string, caret: number): { nextValue: string; nextCaret: number; applied: boolean } {
  const safeCaret = Math.max(0, Math.min(value.length, caret));
  const head = value.slice(0, safeCaret);
  const tail = value.slice(safeCaret);
  const lineStart = head.lastIndexOf("\n") + 1;
  const currentLine = head.slice(lineStart);
  const prefix = getListContinuationPrefix(currentLine);
  if (!prefix) {
    return { nextValue: `${head}\n${tail}`, nextCaret: safeCaret + 1, applied: true };
  }
  const insertion = `\n${prefix}`;
  return {
    nextValue: `${head}${insertion}${tail}`,
    nextCaret: safeCaret + insertion.length,
    applied: true,
  };
}

function detectComposerIntent(text: string, manualMode: MathModeSetting = "auto"): ComposerIntentId {
  const source = (text || "").trim();
  if (!source) {
    return "auto";
  }

  const mathSignals = isMathIntent(source, manualMode);
  const scored = COMPOSER_INTENT_SPECS.map((spec) => {
    let score = 0;
    for (const keyword of spec.keywords) {
      if (keyword.test(source)) {
        score += 1;
      }
    }
    if (spec.id === "math" && mathSignals.isMath) {
      score += 2;
    }
    return { id: spec.id, score };
  });

  scored.sort((a, b) => b.score - a.score);
  if (!scored[0] || scored[0].score <= 0) {
    return "auto";
  }
  return scored[0].id;
}

function extractWordPrefixAtCaret(value: string, caret: number): { prefix: string; wordStart: number; wordEnd: number } | null {
  const safeCaret = Math.max(0, Math.min(value.length, caret));
  const head = value.slice(0, safeCaret);
  const match = /([a-zA-Z][a-zA-Z'-]*)$/.exec(head);
  if (!match) {
    return null;
  }
  const prefix = match[1] || "";
  if (prefix.length < AUTOCOMPLETE_MIN_PREFIX) {
    return null;
  }
  const wordStart = safeCaret - prefix.length;
  let wordEnd = safeCaret;
  while (wordEnd < value.length && /[a-zA-Z'-]/.test(value[wordEnd])) {
    wordEnd += 1;
  }
  return { prefix, wordStart, wordEnd };
}

function rankCompletionCandidate(prefixLower: string, candidate: string): number {
  const delta = candidate.length - prefixLower.length;
  const hyphenPenalty = candidate.includes("-") ? 2 : 0;
  const apostrophePenalty = candidate.includes("'") ? 2 : 0;
  const longPenalty = candidate.length > AUTOCOMPLETE_MAX_WORD_LENGTH ? 4 : 0;
  return delta + hyphenPenalty + apostrophePenalty + longPenalty;
}

function findBestDictionaryCompletion(prefix: string): string {
  const prefixLower = prefix.toLowerCase();
  if (prefixLower.length < AUTOCOMPLETE_MIN_PREFIX) {
    return "";
  }

  let commonBest = "";
  let commonScore = Number.POSITIVE_INFINITY;
  for (const word of NORMALIZED_COMMON_ENGLISH) {
    if (!word.startsWith(prefixLower) || word === prefixLower) {
      continue;
    }
    const score = rankCompletionCandidate(prefixLower, word);
    if (score < commonScore) {
      commonScore = score;
      commonBest = word;
    }
    if (score === 1) {
      break;
    }
  }
  if (commonBest) {
    return commonBest;
  }

  const bucket = ENGLISH_DICTIONARY_BY_PREFIX.get(prefixLower.slice(0, 2));
  if (!bucket || bucket.length === 0) {
    return "";
  }
  let best = "";
  let bestScore = Number.POSITIVE_INFINITY;
  let scanned = 0;
  for (const word of bucket) {
    scanned += 1;
    if (scanned > AUTOCOMPLETE_MAX_BUCKET_SCAN) {
      break;
    }
    if (!word.startsWith(prefixLower) || word === prefixLower) {
      continue;
    }
    const score = rankCompletionCandidate(prefixLower, word);
    if (score < bestScore) {
      bestScore = score;
      best = word;
    }
    if (score === 1) {
      break;
    }
  }
  return best;
}

function buildInlineWordCompletion(value: string, caret: number): InlineWordCompletion | null {
  const safeCaret = Math.max(0, Math.min(value.length, caret));
  const context = extractWordPrefixAtCaret(value, caret);
  if (!context) {
    return null;
  }
  if (safeCaret !== context.wordEnd) {
    return null;
  }
  const suggestion = findBestDictionaryCompletion(context.prefix);
  if (!suggestion || suggestion.length <= context.prefix.length) {
    return null;
  }
  const suffix = suggestion.slice(context.prefix.length);
  if (!suffix || suffix.length > AUTOCOMPLETE_MAX_SUFFIX) {
    return null;
  }
  return {
    prefix: context.prefix,
    suggestion,
    suffix,
    wordStart: context.wordStart,
    wordEnd: context.wordEnd,
  };
}

// ── KaTeX CDN loader ────────────────────────────────────────────────────────
let katexLoaded = false;
let katexLoading = false;
const katexReadyCallbacks: Array<() => void> = [];

function ensureKaTeX(onReady: () => void): void {
  if (katexLoaded) { onReady(); return; }
  katexReadyCallbacks.push(onReady);
  if (katexLoading) return;
  katexLoading = true;
  const cssId = "katex-css";
  if (!document.getElementById(cssId)) {
    const link = document.createElement("link");
    link.id = cssId;
    link.rel = "stylesheet";
    link.href = "https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css";
    document.head.appendChild(link);
  }
  const script = document.createElement("script");
  script.src = "https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js";
  script.defer = true;
  script.onload = () => {
    katexLoaded = true;
    katexLoading = false;
    katexReadyCallbacks.splice(0).forEach((cb) => cb());
  };
  script.onerror = () => { katexLoading = false; };
  document.head.appendChild(script);
}

// ── LaTeX preprocessor — fixes hallucinated/malformed commands from models ──
function cleanLatex(tex: string): string {
  return tex
    // Fix common model hallucinations
    .replace(/\\cosec\b/g, "\\csc")
    .replace(/\\tangent\b/g, "\\tan")
    .replace(/\\cotangent\b/g, "\\cot")
    .replace(/\\csch\b/g, "\\text{csch}")
    .replace(/\\sech\b/g, "\\text{sech}")
    .replace(/\\coscr\b/g, "\\csc")
    .replace(/\\coth\b/g, "\\cot h")
    .replace(/\\cosecant\b/g, "\\csc")
    .replace(/\\tanh\b/g, "\\tanh")
    .replace(/\\tg\b/g, "\\tan")
    .replace(/\\ctg\b/g, "\\cot")
    .replace(/\\arcsec\b/g, "\\text{arcsec}")
    .replace(/\\arccsc\b/g, "\\text{arccsc}")
    .replace(/\\arccot\b/g, "\\text{arccot}")
    // Fix \int missing space before dx/dy
    .replace(/\\int\s*\\tan\b/g, "\\int \\tan")
    .replace(/\\int\s*\\csc\b/g, "\\int \\csc")
    // Remove \boxed with redirect text (model self-correction artifacts)
    .replace(/\\boxed\{[^}]*→[^}]*\}/g, "")
    // Fix \log used as alias for \ln in some notations
    .replace(/\\log\s*\|/g, "\\ln|")
    // Fix spacing around operators
    .replace(/,dx\b/g, "\\,dx")
    .replace(/,dy\b/g, "\\,dy")
    .replace(/,dt\b/g, "\\,dt")
    // Remove stray arrows from model self-corrections
    .replace(/→\s*\\text\{[^}]*\}/g, "")
    .trim();
}

// ── Split content into math and text segments ───────────────────────────────
type ContentSegment =
  | { type: "text"; value: string }
  | { type: "block-math"; value: string }
  | { type: "inline-math"; value: string };

function splitMathSegments(content: string): ContentSegment[] {
  const segments: ContentSegment[] = [];
  // Match $$ ... $$ (block) or $ ... $ (inline), non-greedy
  const pattern = /(\$\$[\s\S]*?\$\$|\$[^$\n]+?\$)/g;
  let lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = pattern.exec(content)) !== null) {
    if (match.index > lastIndex) {
      segments.push({ type: "text", value: content.slice(lastIndex, match.index) });
    }
    const raw = match[0];
    if (raw.startsWith("$$")) {
      segments.push({ type: "block-math", value: cleanLatex(raw.slice(2, -2).trim()) });
    } else {
      segments.push({ type: "inline-math", value: cleanLatex(raw.slice(1, -1).trim()) });
    }
    lastIndex = match.index + raw.length;
  }
  if (lastIndex < content.length) {
    segments.push({ type: "text", value: content.slice(lastIndex) });
  }
  return segments;
}

function hasMathContent(content: string): boolean {
  return /\$\$[\s\S]*?\$\$|\$[^$\n]+?\$/.test(content);
}

// ── Math renderer component (LRU cached renderToString) ─────────────────────
const katexHtmlCache = new Map<string, string>();

function getKaTeXHtml(latex: string, displayMode: boolean): string {
  const cacheKey = `${displayMode ? "D" : "I"}:${latex}`;
  const cached = katexHtmlCache.get(cacheKey);
  if (cached) return cached;
  try {
    const katex = (window as any).katex;
    if (katex?.renderToString) {
      const html = katex.renderToString(latex, { throwOnError: false, displayMode, output: "html" });
      if (katexHtmlCache.size > 400) {
        const firstKey = katexHtmlCache.keys().next().value;
        if (firstKey) katexHtmlCache.delete(firstKey);
      }
      katexHtmlCache.set(cacheKey, html);
      return html;
    }
  } catch {
    // ignore render error
  }
  return "";
}

const KaTeXInline = React.memo(function KaTeXInline({ latex }: { latex: string }) {
  const [ready, setReady] = useState(katexLoaded);
  useEffect(() => {
    if (!katexLoaded) {
      ensureKaTeX(() => setReady(true));
    }
  }, []);
  const html = useMemo(() => (ready ? getKaTeXHtml(latex, false) : ""), [ready, latex]);
  if (!ready || !html) return <span className="math-inline-text">{latex}</span>;
  return <span className="math-inline" dangerouslySetInnerHTML={{ __html: html }} />;
});

const KaTeXBlock = React.memo(function KaTeXBlock({ latex }: { latex: string }) {
  const [ready, setReady] = useState(katexLoaded);
  useEffect(() => {
    if (!katexLoaded) {
      ensureKaTeX(() => setReady(true));
    }
  }, []);
  const html = useMemo(() => (ready ? getKaTeXHtml(latex, true) : ""), [ready, latex]);
  if (!ready || !html) {
    return (
      <div className="math-block-loading">
        <code>{latex}</code>
      </div>
    );
  }
  return <div className="math-block" dangerouslySetInnerHTML={{ __html: html }} />;
});


// ── Smart math-aware markdown renderer ──────────────────────────────────────
function MathAwareContent({ content }: { content: string }) {
  const segments = useMemo(() => splitMathSegments(content), [content]);
  return (
    <>
      {segments.map((seg, i) => {
        if (seg.type === "block-math") {
          return <KaTeXBlock key={i} latex={seg.value} />;
        }
        if (seg.type === "inline-math") {
          return <KaTeXInline key={i} latex={seg.value} />;
        }
        return seg.value ? (
          <span key={i} className="math-text-segment">
            {seg.value}
          </span>
        ) : null;
      })}
    </>
  );
}

function safeBase64Encode(str: string): string {
  try {
    if (typeof window !== "undefined" && window.btoa) {
      return window.btoa(unescape(encodeURIComponent(str)));
    }
    // @ts-ignore
    return Buffer.from(str, "utf-8").toString("base64");
  } catch {
    return "";
  }
}

function safeBase64Decode(b64: string): string {
  try {
    if (typeof window !== "undefined" && window.atob) {
      return decodeURIComponent(escape(window.atob(b64)));
    }
    // @ts-ignore
    return Buffer.from(b64, "base64").toString("utf-8");
  } catch {
    return b64;
  }
}

function protectMathForMarkdown(content: string): string {
  if (!content) return "";

  // 1. Stash all existing fenced code blocks and inline code so we don't mangle code containing '$'
  const codeStash: string[] = [];
  let stashed = content.replace(/(```[\s\S]*?```|`[^`\n]+`)/g, (match) => {
    const placeholder = `⟦CODESTASH_${codeStash.length}⟧`;
    codeStash.push(match);
    return placeholder;
  });

  // 2. Protect \[ ... \] block math
  stashed = stashed.replace(/\\\[([\s\S]*?)\\\]/g, (_match, math) => {
    const clean = cleanLatex(math.trim());
    const encoded = safeBase64Encode(clean);
    return `\n\n\`\`\`math\n${encoded}\n\`\`\`\n\n`;
  });

  // 3. Protect $$ ... $$ block math
  stashed = stashed.replace(/\$\$([\s\S]*?)\$\$/g, (_match, math) => {
    const clean = cleanLatex(math.trim());
    const encoded = safeBase64Encode(clean);
    return `\n\n\`\`\`math\n${encoded}\n\`\`\`\n\n`;
  });

  // 4. Protect \( ... \) inline math
  stashed = stashed.replace(/\\\(([\s\S]*?)\\\)/g, (_match, math) => {
    const clean = cleanLatex(math.trim());
    const encoded = safeBase64Encode(clean);
    return `\`math-inline:${encoded}\``;
  });

  // 5. Protect $...$ inline math: avoid currency like $100, $50, $0.05
  stashed = stashed.replace(/(^|[^\\])\$([^\s$][^$\n]*?[^\s$]|\S)\$/g, (match, prefix, math) => {
    const trimmed = math.trim();
    if (/^\d+(?:,\d{3})*(?:\.\d+)?$/.test(trimmed)) {
      return match;
    }
    const clean = cleanLatex(trimmed);
    const encoded = safeBase64Encode(clean);
    return `${prefix}\`math-inline:${encoded}\``;
  });

  // 6. Restore stashed code blocks
  stashed = stashed.replace(/⟦CODESTASH_(\d+)⟧/g, (_match, index) => {
    return codeStash[Number(index)] ?? "";
  });

  return stashed;
}

function normalizeMarkdownContent(content: string): string {
  let processed = content ?? "";

  processed = processed
    .replace(/(\[[^\]]+\])\(\?meera_mcq=([^)]+)\)/gi, (match, p1, p2) => {
        return `${p1}(?meera_mcq=${encodeURIComponent(p2)})`;
    })
    .replace(/<meera_mcq>[\s\S]*?<\/meera_mcq>/gi, "")
    .replace(/<(?:meera_stage|stage)[^>]*>[\s\S]*?<\/meera_stage>/gi, "")
    .replace(/<meera_stage[^>]*\/?>/gi, "")
    .replace(/(?:^|\n)[^\n<]{0,40}\blabel\s*:[^\n]{0,120}\bdetail\s*:[^\n]{0,200}\bprogress\s*:\s*\d{1,3}[^\n]*?(?:<\/meera_stage>|<\/stage>|$)/gi, "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/\u200b/g, "");

  // Ensure headings have space after hash: e.g. "##Title" -> "## Title", "###1." -> "### 1."
  processed = processed.replace(/(^|\n)(#{1,6})([^\s#\n])/g, "$1$2 $3");

  // Ensure headings start on their own line with a blank line before
  processed = processed.replace(/([^\n])\s*(#{1,6}\s+)/g, "$1\n\n$2");

  // Ensure dividers like *** or --- have clean surrounding blank lines
  processed = processed.replace(/\n(\*{3,}|-{3,}|_{3,})\n/g, "\n\n$1\n\n");

  // Collapse excess blank lines
  processed = processed.replace(/\n{3,}/g, "\n\n").trim();

  return protectMathForMarkdown(processed);
}

// ── Strip and re-inject math so ReactMarkdown doesn't mangle it ─────────────
function extractAndProtectMath(content: string): { protected: string; mathMap: Map<string, ContentSegment> } {
  const mathMap = new Map<string, ContentSegment>();
  let counter = 0;
  const withTokens = content.replace(/(\$\$[\s\S]*?\$\$|\$[^$\n]+?\$)/g, (match) => {
    const token = `MATHTOKEN${counter++}`;
    if (match.startsWith("$$")) {
      mathMap.set(token, { type: "block-math", value: cleanLatex(match.slice(2, -2).trim()) });
    } else {
      mathMap.set(token, { type: "inline-math", value: cleanLatex(match.slice(1, -1).trim()) });
    }
    return ` \`${token}\` `;
  });
  return { protected: withTokens, mathMap };
}

function sanitizeImageUrls(input: unknown, maxItems: number = MAX_REPLY_IMAGES): string[] {
  if (!Array.isArray(input)) {
    return [];
  }
  const results: string[] = [];
  const seen = new Set<string>();
  const trustedImageHosts = [
    "upload.wikimedia.org",
    "picsum.photos",
    "images.unsplash.com",
    "source.unsplash.com",
    "pexels.com",
    "pixabay.com",
    "flickr.com",
    "googleusercontent.com",
    "bing.net",
    "imgur.com",
    "cloudfront.net",
  ];
  const blockedImageMarkers = [
    "porn",
    "xxx",
    "nsfw",
    "adult",
    "sexual",
    "nude",
    "nudity",
    "erotic",
    "onlyfans",
    "hentai",
    "rule34",
    "redgifs",
    "redtube",
    "xvideos",
    "xnxx",
    "xhamster",
    "youporn",
    "camgirl",
    "escort",
    "fetish",
    "gore",
    "graphic",
    "blood",
    "corpse",
    "beheading",
    "decapitated",
    "injury",
    "wound",
    "nsfl",
  ];
  for (const item of input) {
    if (typeof item !== "string") {
      continue;
    }
    const cleaned = item.trim().replace(/[),.;]+$/g, "");
    if (!cleaned || !/^https?:\/\//i.test(cleaned)) {
      continue;
    }
    const lowered = cleaned.toLowerCase();
    if (/\.(pdf|docx?|pptx?|xlsx?|zip|rar|7z|txt|csv|html?)($|[?#])/i.test(lowered)) {
      continue;
    }
    let dedupeKey = cleaned.toLowerCase();
    try {
      const parsed = new URL(cleaned);
      if (parsed.protocol !== "https:") {
        continue;
      }
      const host = parsed.host.toLowerCase().replace(/^www\./, "");
      const path = parsed.pathname.toLowerCase().replace(/\/+$/, "");
      const hostAndPath = `${host}${path}${parsed.search.toLowerCase()}`;
      if (blockedImageMarkers.some((marker) => hostAndPath.includes(marker))) {
        continue;
      }
      const hasImageExtension = /\.(jpg|jpeg|png|gif|webp|bmp|svg|avif)($|[?#])/i.test(path);
      const trustedHost = trustedImageHosts.some((domain) => host === domain || host.endsWith(`.${domain}`));
      if (!hasImageExtension && !trustedHost) {
        continue;
      }
      if (host && path) {
        dedupeKey = `${host}${path}`;
      }
    } catch {
      // keep raw URL fallback key
    }
    if (seen.has(dedupeKey)) {
      continue;
    }
    seen.add(dedupeKey);
    results.push(cleaned);
    if (results.length >= maxItems) {
      break;
    }
  }
  return results;
}

type AssistantVisualStripProps = {
  imageUrls?: string[];
  loading?: boolean;
  onOpenImage?: (urls: string[], index: number) => void;
};

function AssistantVisualStrip({ imageUrls = [], loading = false, onOpenImage }: AssistantVisualStripProps) {
  const normalized = useMemo(() => sanitizeImageUrls(imageUrls), [imageUrls]);
  if (!loading && normalized.length === 0) {
    return null;
  }
  const placeholderCount = Math.max(5, normalized.length || 0);
  return (
    <div className="assistant-visual-strip">
      {loading ? (
        <div className="assistant-visual-loader" aria-hidden="true">
          {Array.from({ length: placeholderCount }).map((_, index) => (
            <span key={`loader-${index}`} style={{ "--loader-index": index } as React.CSSProperties} />
          ))}
        </div>
      ) : null}
      {normalized.length > 0 ? (
        <div className="assistant-visual-grid">
          {normalized.map((url, index) => {
            if (onOpenImage) {
              return (
                <button
                  key={`${url}-${index}`}
                  className="assistant-visual-card assistant-visual-card-button"
                  type="button"
                  onClick={() => onOpenImage(normalized, index)}
                  aria-label={`Open reference image ${index + 1}`}
                >
                  <img
                    src={url}
                    alt={`Reference image ${index + 1}`}
                    loading={index < 2 ? "eager" : "lazy"}
                    decoding="async"
                    referrerPolicy="no-referrer"
                  />
                </button>
              );
            }
            return (
              <a
                key={`${url}-${index}`}
                className="assistant-visual-card"
                href={url}
                target="_blank"
                rel="noreferrer"
                aria-label={`Open reference image ${index + 1}`}
              >
                <img
                  src={url}
                  alt={`Reference image ${index + 1}`}
                  loading={index < 2 ? "eager" : "lazy"}
                  decoding="async"
                  referrerPolicy="no-referrer"
                />
              </a>
            );
          })}
        </div>
      ) : null}
    </div>
  );
}

type CommandRunResult = {
  command: string;
  output: string;
  shell: string;
  ok: boolean;
  exitCode: number;
  explanation: string;
};

function parseCommandRunResult(content: string): CommandRunResult | null {
  const text = (content || "").trim();
  if (!/^terminal result\b/i.test(text)) return null;
  const commandMatch = text.match(/Command:\s*```([a-z0-9_-]*)\n([\s\S]*?)```/i);
  const outputMatch = text.match(/Output:\s*```([a-z0-9_-]*)\n([\s\S]*?)```/i);
  const command = commandMatch?.[2]?.trimEnd() ?? "";
  const shell = commandMatch?.[1]?.trim() || "powershell";
  const output = outputMatch?.[2]?.trimEnd() ?? "";
  const exitMatch = text.match(/Completed with exit code\s+(-?\d+)/i);
  const exitCode = exitMatch ? Number(exitMatch[1]) : /failed|error|not recognized|invalid/i.test(output) ? 1 : 0;
  const explanation = text
    .replace(/^terminal result\b/i, "")
    .replace(/Command:\s*```([a-z0-9_-]*)\n([\s\S]*?)```/i, "")
    .replace(/Output:\s*```([a-z0-9_-]*)\n([\s\S]*?)```/i, "")
    .replace(/Completed with exit code\s+-?\d+\.?/i, "")
    .replace(/^Analysis:\s*/i, "")
    .trim();
  if (!command && !output) return null;
  return {
    command,
    output,
    shell,
    exitCode,
    explanation,
    ok: exitCode === 0 && !/(error|failed|not recognized|invalid|exception|traceback|parsererror)/i.test(output),
  };
}

function summarizeShellCommand(command: string): string {
  const trimmed = (command || "").trim();
  if (!trimmed) return "Ran a command";
  const firstLine = trimmed.split("\n")[0].trim();
  const collapsed = firstLine.length > 64 ? `${firstLine.slice(0, 61)}…` : firstLine;
  return collapsed;
}

function ClaudeThinkingCard({ content, isLive, title }: { content: string, isLive?: boolean, title?: string }) {
  const [expanded, setExpanded] = useState(false);

  if (!content) return null;

  return (
    <div style={{ margin: "16px 0", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif" }}>
      <div 
        onClick={() => setExpanded(!expanded)}
        style={{
          display: "inline-flex",
          alignItems: "center",
          gap: "8px",
          color: "var(--text-1)",
          fontSize: "14px",
          fontWeight: "650",
          cursor: "pointer",
          userSelect: "none",
          marginBottom: expanded ? "12px" : "0",
          padding: "4px 8px 4px 2px",
          borderRadius: "6px",
          transition: "background 0.15s ease"
        }}
        onMouseEnter={(e) => e.currentTarget.style.background = "rgba(15, 23, 42, 0.04)"}
        onMouseLeave={(e) => e.currentTarget.style.background = "transparent"}
      >
        <motion.span
          animate={{ rotate: expanded ? 90 : 0 }}
          transition={{ duration: 0.15 }}
          style={{ color: "var(--text-3)", display: "flex" }}
        >
          <PiCaretRight size={14} style={{ strokeWidth: 2 }} />
        </motion.span>
        {title || (isLive ? "Thinking..." : "Reasoning")}
      </div>

      <AnimatePresence initial={false}>
        {expanded && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
            style={{ overflow: "hidden" }}
          >
            <div style={{
              background: "transparent",
              border: "none",
              padding: "8px 16px",
              display: "flex",
              flexDirection: "column",
              gap: "20px",
              marginLeft: "6px",
              boxShadow: "none"
            }}>
              <div style={{ 
                margin: 0, 
                fontSize: "14px", 
                color: "var(--text-1)",
                whiteSpace: "pre-wrap",
                wordBreak: "break-word",
                lineHeight: "1.6"
              }}>
                <PlainMarkdownContent content={content} />
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* @ts-ignore */}
      {hasAnswerContent ? <div className="rt-divider" aria-hidden="true" /> : null}
    </div>
  );
}

