  useLayoutEffect(() => {
    if (!pendingFreshQueryScrollId || view !== "workspace") {
      return;
    }
    let firstFrame = 0;
    let secondFrame = 0;
    const retryTimer = window.setTimeout(() => {
      scrollFreshQueryToTop(pendingFreshQueryScrollId);
    }, 80);
    firstFrame = window.requestAnimationFrame(() => {
      scrollFreshQueryToTop(pendingFreshQueryScrollId);
      secondFrame = window.requestAnimationFrame(() => {
        scrollFreshQueryToTop(pendingFreshQueryScrollId);
      });
    });

    return () => {
      window.clearTimeout(retryTimer);
      if (firstFrame) {
        window.cancelAnimationFrame(firstFrame);
      }
      if (secondFrame) {
        window.cancelAnimationFrame(secondFrame);
      }
    };
  }, [
    pendingFreshQueryScrollId,
    view,
    scrollFreshQueryToTop,
  ]);



  useEffect(() => {
    if (!feedRef.current || !autoScroll || pendingFreshQueryScrollId || lockFreshQueryToTop) {
      return;
    }
    const feed = feedRef.current;

    if (isSending) {
      if (!isFeedNearBottomRef.current) {
        return;
      }
    } else {
      // Streaming just finished. isFeedNearBottom can be stale here --
      // it only updates on actual scroll events, not when new content
      // grows the container's height. The final answer chunk can arrive
      // as one large jump (recovered/appended in fewer, bigger pieces
      // than a token-by-token stream) in the same tick isSending flips
      // to false, so re-measure the real current distance from bottom
      // fresh right now instead of trusting the possibly-outdated flag.
      const remaining = feed.scrollHeight - feed.scrollTop - feed.clientHeight;
      if (remaining > 96) {
        return;
      }
    }
    
    // We only want to push the scrollbar down if the text has grown PAST the bottom of the viewport.
    // targetTop calculates the exact scroll position where the bottom of the text touches the bottom of the screen.
    const targetTop = Math.max(0, feed.scrollHeight - feed.clientHeight);
    
    // If targetTop > feed.scrollTop, the text has pushed below the screen, so we scroll down to follow it.
    // If it's less, the text is still generating on-screen, so we stay anchored to the top of the message.
    if (targetTop > feed.scrollTop) {
      feed.scrollTo({ top: targetTop, behavior: "auto" });
    }
  }, [visibleMessages, autoScroll, isSending, pendingFreshQueryScrollId, lockFreshQueryToTop]);

