  const normalizeRedditImageUrl = (url: string): string => url?.replace(/&amp;/g, "&");

  const extractRedditImageUrl = (item: any): string | undefined => {
    if (!item) {
      return undefined;
    }

    const previewUrl = item?.preview?.images?.[0]?.source?.url;
    if (previewUrl) {
      return normalizeRedditImageUrl(previewUrl);
    }

    const overridden = item?.url_overridden_by_dest || item?.url;
    if (typeof overridden === "string" && /\.(jpe?g|png|gif|webp)(?:\?|$)/i.test(overridden)) {
      return normalizeRedditImageUrl(overridden);
    }

    if (item?.media_metadata && item.gallery_data?.items?.length) {
      const firstGalleryId = item.gallery_data.items[0]?.media_id;
      const metadata = item.media_metadata?.[firstGalleryId];
      const galleryUrl = metadata?.s?.u || metadata?.p?.[0]?.u;
      if (galleryUrl) {
        return normalizeRedditImageUrl(galleryUrl);
      }
    }

    if (typeof item?.thumbnail === "string" && item.thumbnail.startsWith("http")) {
      return normalizeRedditImageUrl(item.thumbnail);
    }

    return undefined;
  };

  const parseRedditSearchResults = (payload: any): RedditWallpaperResult[] => {
    if (!payload?.data?.children || !Array.isArray(payload.data.children)) {
      return [];
    }

    return payload.data.children
      .map((child: any) => child?.data)
      .map((item: any) => ({
        item,
        imageUrl: extractRedditImageUrl(item),
      }))
      .filter(
        // @ts-ignore
        ({ item, imageUrl }) =>
          Boolean(imageUrl) && !item?.over_18 && typeof imageUrl === "string",
      )
      // @ts-ignore
      .map(({ item, imageUrl }) => ({
        id: item.id || item.name || imageUrl,
        title: item.title || "Wallpaper",
        imageUrl: imageUrl as string,
        subreddit: item.subreddit_name_prefixed || item.subreddit || "r/wallpapers",
        permalink: `https://reddit.com${item.permalink || ""}`,
      }))
      .slice(0, REDDIT_SEARCH_MAX_RESULTS);
  };

  const buildRedditSearchUrls = (query: string): string[] => {
    const searchQuery = encodeURIComponent(`${query} wallpaper`);
    const urls = [
      `https://www.reddit.com/search.json?q=${searchQuery}&sort=top&limit=50&include_over_18=0&type=link`,
      `https://www.reddit.com/r/wallpapers/search.json?q=${encodeURIComponent(query)}&restrict_sr=1&sort=top&limit=50&type=link`,
    ];

    if (/^[a-zA-Z0-9_]+$/.test(query)) {
      urls.push(`https://www.reddit.com/r/${query}/top.json?limit=50&t=week`);
    }

    REDDIT_FALLBACK_SUBREDDITS.forEach((subreddit) => {
      if (!urls.includes(subreddit)) {
        urls.push(`https://www.reddit.com/r/${subreddit}/top.json?limit=50&t=week`);
      }
    });

    return urls;
  };

  const buildFallbackWallpaperResults = (query: string, limit = 15, width = 2560, height = 1440): RedditWallpaperResult[] =>
    Array.from({ length: limit }, (_, index) => {
      const sig = index + 1;
      const term = query ? encodeURIComponent(query) : "wallpaper";
      const seed = `${term}-${sig}`;
      const imageUrl = `https://picsum.photos/seed/${seed}/${width}/${height}`;
      const thumbnailUrl = `https://picsum.photos/seed/${seed}/640/360`;
      return {
        id: `fallback-wallpaper-${query}-${sig}`,
        title: query ? `Wallpaper: ${query}` : "Wallpaper",
        imageUrl,
        thumbnailUrl,
        subreddit: "Photography",
        permalink: imageUrl,
      };
    });

  const searchRedditWallpapers = async (queryOverride?: string) => {
    const query = (queryOverride ?? redditSearchQuery).trim();
    setRedditSearchQuery(query);
    if (!query) {
      setRedditSearchError("Enter a search term to fetch wallpaper previews.");
      setRedditSearchResults([]);
      return;
    }
    setRedditSearchLoading(true);
    setRedditSearchError("");
    setRedditSearchResults([]);

    // Build a wallpaper-optimized search query for the backend
    const wallpaperQuery = `${query} wallpaper 4k high quality`;

    const mapJsonToResults = (json: any): RedditWallpaperResult[] => {
      if (!Array.isArray(json)) {
        return [];
      }
      return json
        .filter((item: any) => item && item.imageUrl)
        .slice(0, 15)
        .map((item: any) => ({
          id: String(item.id || item.imageUrl),
          title: String(item.title || ""),
          imageUrl: String(item.imageUrl),
          thumbnailUrl: String(item.thumbnailUrl || item.imageUrl),
          subreddit: String(item.subreddit || ""),
          permalink: String(item.permalink || item.imageUrl || ""),
        }));
    };

    // Map backend ImageSearchResponse to RedditWallpaperResult
    const mapBackendImageResults = (data: any): RedditWallpaperResult[] => {
      const images = data?.images || [];
      return images
        .filter((img: any) => img?.url)
        .slice(0, 15)
        .map((img: any) => ({
          id: img.url,
          title: img.title || query,
          imageUrl: img.url,
          thumbnailUrl: img.thumbnail_url || img.url,
          subreddit: img.source || "Meera Search",
          permalink: img.url,
        }));
    };

    try {
      let results: RedditWallpaperResult[] = [];

      // Try the backend's enhanced image search API first (has wallpaper query enhancement)
      try {
        const backendResp = await fetch(`${API_BASE}/api/images/search?q=${encodeURIComponent(wallpaperQuery)}&max_results=15`, {
          headers: { Accept: "application/json" },
        });
        if (backendResp.ok) {
          const backendData = await backendResp.json();
          results = mapBackendImageResults(backendData);
        }
      } catch { /* fall through to other sources */ }

      // Fallback: try the dedicated wallpapers/unsplash endpoint
      if (results.length === 0) {
        const unsplashResp = await fetch(`${API_BASE}/api/wallpapers/unsplash?q=${encodeURIComponent(query)}&limit=15&width=2560&height=1440`, {
          headers: { Accept: "application/json" },
        });

        if (unsplashResp.ok) {
          const payload = await unsplashResp.json();
          results = mapJsonToResults(payload);
        }
      }

      if (results.length > 0) {
        setRedditSearchResults(results);
        setRedditLastQuery(query);
        setRedditSearchLoading(false);
        return;
      }

      // Fallback: Generate relevant real wallpapers if no results
      const fallbackResults = buildFallbackWallpaperResults(query, 15);
      setRedditSearchResults(fallbackResults);
      setRedditLastQuery(query);
    } catch (err) {
      // Fallback on error too
      const fallbackResults = buildFallbackWallpaperResults(query, 15);
      setRedditSearchResults(fallbackResults);
      setRedditLastQuery(query);
      setRedditSearchError("");
    } finally {
      setRedditSearchLoading(false);
    }
  };

  const useRedditWallpaper = async (result: RedditWallpaperResult) => {
    // Optimistically update to the remote URL so it updates instantly
    updateAppearance((appearance) => ({
      ...appearance,
      wallpaperId: DEFAULT_WALLPAPER_ID,
      customWallpaper: result.imageUrl,
      customWallpaperName: `${result.title} • ${result.subreddit}`,
    }));

    try {
      // Fetch the image to cache it locally as a Data URL to prevent expiration
      let response = await fetch(result.imageUrl).catch(() => null);
      if (!response || !response.ok) {
        // Fallback to proxy to bypass CORS if direct fetch fails
        response = await fetch(`${API_BASE}/api/documents/proxy?url=${encodeURIComponent(result.imageUrl)}`);
      }
      if (response && response.ok) {
        const blob = await response.blob();
        const reader = new FileReader();
        reader.onloadend = () => {
          const dataUrl = reader.result as string;
          updateAppearance((appearance) => ({
            ...appearance,
            wallpaperId: DEFAULT_WALLPAPER_ID,
            customWallpaper: dataUrl,
            customWallpaperName: `${result.title} • ${result.subreddit}`,
          }));
        };
        reader.readAsDataURL(blob);
      }
    } catch (e) {
      console.error("Failed to download wallpaper locally, it may expire or change.", e);
    }
  };

