                        <img
                          className="auth-social-logo github"
                          src={AUTH_PROVIDER_ICON_URLS.github}
                          alt="GitHub"
                          width={16}
                          height={16}
                          loading="lazy"
                          decoding="async"
                          referrerPolicy="no-referrer"
                        />
