                          {pendingAttachments.length > 0 ? (
                            <div className="chat-attachment-tray workspace" aria-label="Attached files">
                              {pendingAttachments.map((file) => {
                                const isImage = file.type.startsWith("image/") || /\.(png|jpe?g|gif|webp|svg)$/i.test(file.name);
                                if (isImage) {
                                  return (
                                    <div
                                      className="chat-attachment-chip has-image-preview"
                                      key={file.id}
                                      role="button"
                                      tabIndex={0}
                                      aria-label={`Preview ${file.name}`}
                                      onClick={() => {
                                        if (file.content_base64) {
                                          openAttachmentViewer(file);
                                        }
                                      }}
                                      onKeyDown={(event) => {
                                        if (event.key === "Enter" || event.key === " ") {
                                          event.preventDefault();
                                          openAttachmentViewer(file);
                                        }
                                      }}
                                    >
                                      <div className="chat-attachment-image-container">
                                        <img
                                          src={`data:${file.type && file.type !== "application/octet-stream" ? file.type : 'image/png'};base64,${file.content_base64}`}
                                          alt={file.name}
                                          className="chat-attachment-image-preview"
                                        />
                                      </div>
                                      <span className="chat-attachment-copy">
                                        <span className="chat-attachment-name">{file.name}</span>
                                        <span className="chat-attachment-size">{formatAttachmentSize(file.size)}</span>
                                      </span>
                                      <button
                                        className="chat-attachment-remove"
                                        type="button"
                                        aria-label={`Remove ${file.name}`}
                                        onClick={() => removePendingAttachment(file.id)}
                                      >
                                        <PiX />
                                      </button>
                                    </div>
                                  );
                                }

                                // Non-image document vertical card layout
                                const isPdf = file.name.toLowerCase().endsWith(".pdf") || file.type === "application/pdf";
                                const isOffice = /docx?|xlsx?|pptx?/i.test(file.name);
                                const isCode = /txt|md|py|js|json|html|css|xml|yaml/i.test(file.name);
                                const themeClass = isPdf ? "pdf-theme" : isOffice ? "office-theme" : isCode ? "code-theme" : "generic-theme";
                                const iconName = isPdf ? "picture_as_pdf" : isOffice ? "description" : isCode ? "code" : "folder_open";

                                if (isPdf && file.blobUrl) {
                                  return (
                                    <div
                                      className="chat-attachment-chip has-image-preview"
                                      key={file.id}
                                      role="button"
                                      tabIndex={0}
                                      aria-label={`Preview ${file.name}`}
                                      onClick={() => {
                                        if (file.content_base64) {
                                          openAttachmentViewer(file);
                                        }
                                      }}
                                      onKeyDown={(event) => {
                                        if (event.key === "Enter" || event.key === " ") {
                                          event.preventDefault();
                                          openAttachmentViewer(file);
                                        }
                                      }}
                                    >
                                      <div className="chat-attachment-image-container has-iframe-preview">
                                        <iframe
                                          src={`${file.blobUrl}#toolbar=0&navpanes=0&scrollbar=0`}
                                          title={file.name}
                                          scrolling="no"
                                        />
                                        {/* @ts-ignore */}
                                        {file.previewLoading && (
                                          <div className="doc-preview-loading-spinner" />
                                        )}
                                      </div>
                                      <span className="chat-attachment-copy">
                                        <span className="chat-attachment-name">{file.name}</span>
                                        <span className="chat-attachment-size">{formatAttachmentSize(file.size)}</span>
                                      </span>
                                      <button
                                        className="chat-attachment-remove"
                                        type="button"
                                        aria-label={`Remove ${file.name}`}
                                        onClick={() => removePendingAttachment(file.id)}
                                      >
                                        <PiX />
                                      </button>
                                    </div>
                                  );
                                }

                                return (
                                  <div
                                    className="chat-attachment-chip has-image-preview has-doc-preview"
                                    key={file.id}
                                    role="button"
                                    tabIndex={0}
                                    aria-label={`Preview ${file.name}`}
                                    onClick={() => {
                                      if (file.content_base64) {
                                        openAttachmentViewer(file);
                                      }
                                    }}
                                    onKeyDown={(event) => {
                                      if (event.key === "Enter" || event.key === " ") {
                                        event.preventDefault();
                                        openAttachmentViewer(file);
                                      }
                                    }}
                                  >
                                    <div className={`chat-attachment-image-container doc-preview-bg ${themeClass}`}>
                                      <span className="material-symbols-outlined doc-preview-icon">{iconName}</span>
                                      {/* @ts-ignore */}
                                      {file.previewLoading && (
                                        <div className="doc-preview-loading-spinner" />
                                      )}
                                    </div>
                                    <span className="chat-attachment-copy">
                                      <span className="chat-attachment-name">{file.name}</span>
                                      <span className="chat-attachment-size">{formatAttachmentSize(file.size)}</span>
                                    </span>
                                    <button
                                      className="chat-attachment-remove"
                                      type="button"
                                      aria-label={`Remove ${file.name}`}
                                      onClick={() => removePendingAttachment(file.id)}
                                    >
                                      <PiX />
                                    </button>
                                  </div>
                                );
                              })}
                            </div>
                          ) : null}
